'use strict';
const scenarios = {
  edited: { id: 'LZ-DEMO-2048', name: 'Nồi chiên không dầu AirHome', shop: 'AirHome Official · shop giả lập', price: '1.290.000 ₫', icon: '▥', original: 'Dung tích 6 lít · Công suất 1.700 W', current: 'Dung tích 5 lít · Công suất 1.700 W', buyer: 'Mình mua nồi chiên ghi 6 lít, nhận về chỉ có 5 lít. Giờ vào xem shop lại sửa thành 5 lít rồi. Mình muốn trả hàng hoàn tiền.', seller: 'Shop cho rằng mô tả hiện tại là 5 lít. Chưa giải thích thay đổi so với bản lúc đặt.', reply: 'Mình đã ghi nhận vấn đề dung tích. Bản mô tả lưu lúc bạn đặt ghi 6 lít, trong khi mô tả hiện tại ghi 5 lít. Tôi là trợ lý AI, chưa thể kết luận bên nào đúng.\n\nTôi có thể giúp bạn bổ sung ảnh tem sản phẩm và chuyển hồ sơ cho nhân viên đối chiếu. Chưa có thao tác hoàn tiền hoặc từ chối nào được thực hiện.', uncertainty: 'Có thay đổi giữa hai phiên bản mô tả. Cần kiểm tra dung tích ghi trên tem và phản hồi người bán; không dùng mô tả hiện tại để bác yêu cầu.', evidence: [['Bản mô tả lúc đặt: 6 lít', 'Bản lưu giả lập · 08/11/2026', false], ['Mô tả hiện tại: 5 lít', 'Khác bản lúc đặt · cần đối chiếu', true], ['Ảnh tem sản phẩm: chưa có', 'Cần người mua bổ sung', true]] },
  measurement: { id: 'LZ-DEMO-2051', name: 'Nồi chiên không dầu AirHome', shop: 'AirHome Official · shop giả lập', price: '1.290.000 ₫', icon: '▥', original: 'Dung tích công bố 6 lít', current: 'Dung tích công bố 6 lít', buyer: 'Tem ghi 6 lít nhưng mình đong lòng nồi chỉ được 5 lít. Mình nghĩ hàng không đúng mô tả, hoàn tiền giúp mình.', seller: 'Tem sản phẩm ghi 6 lít, khớp mô tả. Shop chưa cung cấp tài liệu giải thích phương pháp đo.', reply: 'Ảnh tem trong hồ sơ ghi 6 lít, khớp bản mô tả lúc đặt. Tuy nhiên, tôi chưa có căn cứ giải thích chênh lệch với cách bạn đo.\n\nTôi là trợ lý AI, chưa thể kết luận sản phẩm sai mô tả hoặc từ chối yêu cầu. Bạn có thể bổ sung ảnh cách đo; nhân viên sẽ đối chiếu cùng phản hồi của shop.', uncertainty: 'Không suy diễn dung tích công bố tương đương kết quả đong. Cần ảnh cách đo và thông tin kỹ thuật từ người bán. Chưa đủ căn cứ để hoàn tiền hoặc từ chối.', evidence: [['Mô tả lúc đặt: 6 lít', 'Khớp bản mô tả hiện tại', false], ['Ảnh tem giả lập: 6 lít', 'Khớp dung tích công bố', false], ['Cách đo: chưa được xác minh', 'Cần ảnh minh họa và phản hồi shop', true]] },
  normal: { id: 'LZ-DEMO-2060', name: 'Áo thun Basic Cotton · Size L', shop: 'Everyday Wear · shop giả lập', price: '189.000 ₫', icon: '♧', original: 'Áo thun Basic Cotton · Size L', current: 'Áo thun Basic Cotton · Size L', buyer: 'Mình đặt size L mà nhận được size M, mặc không vừa. Shop đã nhắn nhận là gửi nhầm rồi. Mình muốn trả hàng hoàn tiền thì làm sao?', seller: 'Shop xác nhận gửi nhầm size M và đồng ý tiếp nhận yêu cầu trả hàng.', reply: 'Bản đặt hàng ghi size L, ảnh tem giả lập ghi size M và shop đã xác nhận gửi nhầm. Tôi là trợ lý AI, có thể giúp bạn chuẩn bị hồ sơ trả hàng/hoàn tiền.\n\nBạn có thể chuyển hồ sơ cho nhân viên duyệt. Đây chưa phải thông báo hoàn tiền thành công; không cần gửi lại bằng chứng đã có.', uncertainty: 'Các bằng chứng hiện có thống nhất. Nhân viên kiểm tra hồ sơ và xác nhận phương án trả hàng/hoàn tiền; không yêu cầu người mua gửi lại ảnh đã có.', evidence: [['Đơn hàng: Size L', 'Bản lưu lúc đặt hàng', false], ['Ảnh tem giả lập: Size M', 'Khác kích cỡ đã đặt', false], ['Shop xác nhận gửi nhầm', 'Phản hồi đã có trong fixture', false]] }
};
let state, pendingDecision, toastTimer;
const $ = id => document.getElementById(id);
function element(tag, className, content) { const el = document.createElement(tag); if (className) el.className = className; if (content !== undefined) el.textContent = content; return el; }
function notify(message) { $('toast').textContent = message; $('toast').hidden = false; clearTimeout(toastTimer); toastTimer = setTimeout(() => $('toast').hidden = true, 3500); }
function addMessage(text, role = 'assistant') { state.messages.push({ text, role }); renderMessages(); }
function renderMessages() { const box = $('messages'); box.replaceChildren(element('div', 'day-divider', 'HÔM NAY · PHIÊN MÔ PHỎNG')); for (const msg of state.messages) { const row = element('div', `message ${msg.role}`); if (msg.role !== 'user') row.append(element('span', 'message-avatar', '✦')); const body = element('div'); body.append(element('div', 'bubble', msg.text)); if (msg.role !== 'user') body.append(element('div', 'message-caption', msg.role === 'system' ? 'Cập nhật hồ sơ · mô phỏng' : 'LazResolve AI · dựa trên dữ liệu hồ sơ')); row.append(body); box.append(row); } box.scrollTop = box.scrollHeight; }
function action(label, callback) { const button = element('button', '', label); button.type = 'button'; button.onclick = callback; return button; }
function renderActions() { const box = $('quick-actions'); box.replaceChildren(); if (state.decision) { box.append(action('Xem quyết định của nhân viên', () => switchView('agent'))); return; } if (!state.submitted) box.append(action('Chuyển hồ sơ cho nhân viên', submitCase)); if (state.key !== 'normal' && !state.evidenceAdded) box.append(action('＋ Bổ sung bằng chứng mẫu ②', addEvidence)); box.append(action('Sửa thông tin · G9', () => { $('chat-input').value = 'Tôi muốn sửa thông tin: '; $('chat-input').focus(); })); if (state.submitted) box.append(action('Xem bàn xử lý nhân viên →', () => switchView('agent'))); }
function renderEvidence() { const box = $('buyer-evidence'); box.replaceChildren(); const items = [...scenarios[state.key].evidence]; if (state.evidenceAdded) { items[2] = ['Đã bổ sung bằng chứng mẫu', state.key === 'edited' ? 'Ảnh tem ghi 5 lít · chưa được nhân viên xác minh' : 'Ảnh minh họa cách đo · chưa được nhân viên xác minh', true]; } for (const [title, detail, warn] of items) { const row = element('div', 'evidence-item'); row.append(element('span', `evidence-check${warn ? ' warn' : ''}`, warn ? '!' : '✓')); const body = element('div'); body.append(element('strong', '', title), element('p', '', detail)); row.append(body); box.append(row); } }
function renderProgress() { const current = state.decision ? 3 : state.submitted ? 2 : 1; const steps = [['Tiếp nhận khiếu nại', 'Đã ghi nhận nội dung của bạn'], ['Đối chiếu & bổ sung', state.evidenceAdded ? 'Bằng chứng mới đang chờ kiểm tra' : 'Kiểm tra nguồn và thông tin còn thiếu'], ['Nhân viên xem xét', state.submitted ? 'Đã chuyển · chưa có quyết định' : 'AI không tự quyết định hoàn tiền'], ['Thông báo kết quả', state.decision ? 'Đã có quyết định mô phỏng' : 'Cập nhật sau khi được duyệt']]; $('progress').replaceChildren(); steps.forEach(([title, detail], i) => { const li = element('li', i < current ? 'done' : i === current ? 'current' : ''); li.append(element('span', 'step-dot', i < current ? '✓' : String(i + 1))); const text = element('span', 'step-text', title); text.append(element('small', '', detail)); li.append(text); $('progress').append(li); }); }
function renderAgent() { const s = scenarios[state.key]; $('comparison').replaceChildren(); const grid = element('div', 'comparison-grid'); [['MÔ TẢ LÚC ĐẶT', s.original, '08/11/2026 · bản lưu fixture'], ['MÔ TẢ HIỆN TẠI', s.current, '13/11/2026 · dữ liệu fixture']].forEach(([label, text, date], i) => { const block = element('div', `comparison-block${i ? ' current' : ''}`); block.append(element('strong', '', label), element('p', '', text), element('small', '', date)); grid.append(block); }); $('comparison').append(grid); $('buyer-statement').textContent = s.buyer; $('seller-statement').textContent = s.seller; $('uncertainty').textContent = s.uncertainty + (state.evidenceAdded ? ' Người mua vừa bổ sung bằng chứng mẫu, cần kiểm tra trước khi quyết định.' : ''); $('agent-status').textContent = state.decision ? 'Đã quyết định · mô phỏng' : state.submitted ? 'Chờ nhân viên duyệt' : 'Chưa gửi hồ sơ'; $('history').replaceChildren(...state.history.map(text => element('li', '', text))); updateDecisionButtons(); }
function updateDecisionButtons() { const disabled = !state.submitted || !!state.decision || !$('review-check').checked || $('decision-reason').value.trim().length < 12; $('approve').disabled = disabled; $('reject').disabled = disabled; $('request-more').disabled = !state.submitted || !!state.decision; }
function render() { renderEvidence(); renderProgress(); renderActions(); renderAgent(); }
function submitCase() { if (state.submitted || state.decision) return; state.submitted = true; state.history.push('Đã chuyển hồ sơ cho nhân viên; mô phỏng thông báo tới cả hai bên. Chưa chuyển tiền.'); addMessage('Hồ sơ đã được chuyển trong phiên mô phỏng. Nhân viên sẽ xem bản mô tả lúc đặt, bằng chứng và phản hồi hai bên. Chưa có quyết định hoàn tiền hoặc từ chối.\n\nBạn vẫn có thể sửa thông tin hoặc bổ sung bằng chứng.', 'system'); render(); notify('Đã chuyển hồ sơ · mở bàn xử lý để tiếp tục demo'); }
function addEvidence() { if (state.evidenceAdded || state.decision) return; state.evidenceAdded = true; state.history.push('Người mua bổ sung bằng chứng mẫu; chưa được nhân viên xác minh.'); addMessage(state.key === 'edited' ? 'Tôi bổ sung ảnh tem mẫu: dung tích ghi 5 lít.' : 'Tôi bổ sung ảnh mẫu minh họa cách đong dung tích.', 'user'); addMessage('Đã gắn bằng chứng mẫu vào hồ sơ. Việc nhận bằng chứng chưa đồng nghĩa với xác minh nội dung hoặc chấp nhận hoàn tiền.'); render(); }
function switchView(view) { const isAgent = view === 'agent'; $('buyer-view').hidden = isAgent; $('agent-view').hidden = !isAgent; document.querySelectorAll('[data-view]').forEach(button => button.classList.toggle('active', button.dataset.view === view)); $('page-title').textContent = isAgent ? 'Mỗi quyết định, một căn cứ rõ ràng.' : 'Cùng làm rõ vấn đề của bạn.'; $('page-subtitle').textContent = isAgent ? 'Xem thông tin hai bên và kiểm tra bằng chứng trước khi quyết định.' : 'Theo dõi bằng chứng, bổ sung thông tin và biết chính xác bước tiếp theo.'; }
function loadScenario() { const key = $('scenario').value, s = scenarios[key]; state = { key, submitted: false, evidenceAdded: false, decision: null, messages: [], history: ['Hệ thống nạp hồ sơ và bằng chứng giả lập. Chưa thực hiện thao tác tài chính.'] }; $('review-check').checked = false; $('decision-reason').value = ''; $('chat-input').value = ''; $('order-id').textContent = s.id; $('breadcrumb-id').textContent = s.id; $('product-name').textContent = s.name; $('shop-name').textContent = s.shop; $('product-price').textContent = s.price; $('product-art').textContent = s.icon; addMessage(s.buyer, 'user'); addMessage(s.reply); render(); switchView('buyer'); }
function prepareDecision(type) { if ($('approve').disabled) return; pendingDecision = type; $('confirm-title').textContent = type === 'refund' ? 'Duyệt phương án hoàn tiền?' : 'Đóng và từ chối khiếu nại?'; $('confirm-description').textContent = `Hồ sơ ${scenarios[state.key].id}. Bạn đang xác nhận với vai trò nhân viên, sau khi kiểm tra bằng chứng hai bên.`; $('confirm-reason').textContent = $('decision-reason').value.trim(); $('confirm-dialog').showModal(); }
$('confirm-dialog').addEventListener('close', () => { if ($('confirm-dialog').returnValue !== 'confirm') return; state.decision = pendingDecision; const result = pendingDecision === 'refund' ? 'Nhân viên đã duyệt phương án trả hàng/hoàn tiền mô phỏng.' : 'Nhân viên đã từ chối khiếu nại mô phỏng.'; const reason = $('decision-reason').value.trim(); state.history.push(`${result} Căn cứ: ${reason}`); addMessage(`${result}\nLý do: ${reason}\n\nĐây là kết quả demo. Không có tiền thật được chuyển.`, 'system'); render(); notify('Đã cập nhật kết quả mô phỏng cho hai bên'); });
$('request-more').onclick = () => { state.history.push('Nhân viên yêu cầu bổ sung bằng chứng; chưa ra quyết định.'); addMessage('Nhân viên cần làm rõ bằng chứng trước khi quyết định. Vui lòng bổ sung phần chưa xác minh được nêu trong hồ sơ. Chưa hoàn tiền hoặc đóng khiếu nại.', 'system'); render(); notify('Đã gửi yêu cầu bổ sung mô phỏng'); };
$('chat-form').onsubmit = event => { event.preventDefault(); const input = $('chat-input'), text = input.value.trim(); if (!text) return; if (state.decision) { notify('Hồ sơ demo đã có quyết định. Bấm Bắt đầu lại để thử tiếp.'); return; } addMessage(text, 'user'); input.value = ''; state.history.push('Người mua bổ sung/sửa thông tin qua chat; cần nhân viên kiểm tra.'); addMessage('Đã ghi nhận nội dung bạn bổ sung vào hồ sơ. Đây là phản hồi mô phỏng, tôi chưa tự xác minh được thông tin mới. Bạn có thể chuyển hồ sơ cho nhân viên kiểm tra; chưa có thao tác hoàn tiền hoặc từ chối tự động.'); render(); };
document.querySelectorAll('[data-view]').forEach(button => button.onclick = () => switchView(button.dataset.view));
$('review-check').onchange = updateDecisionButtons; $('decision-reason').oninput = updateDecisionButtons;
$('approve').onclick = () => prepareDecision('refund'); $('reject').onclick = () => prepareDecision('reject');
$('scenario').onchange = loadScenario; $('reset').onclick = loadScenario;
loadScenario();
